import { expect, test } from "../../fixtures";

test.describe("review queue access", () => {
  test("members cannot see the review queue", { tag: "@REV-04" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");

    // Act
    const response = await member.get("/api/review-queue");

    // Assert
    const body = await response.text();
    expect(response.status(), body).toBe(403);
    const error = (JSON.parse(body) as { error?: { code?: string } }).error;
    expect(error?.code, body).toBe("forbidden");
  });
});
